```cpp
#include <memory>
#include <string>
#include <utility>
#include <stdexcept>
struct PaymentError : std::runtime_error { using std::runtime_error::runtime_error; };
struct IPayMethod {
    /* ① */
    virtual std::string pay(int cents) = 0;
};
struct CardPay : IPayMethod {
    std::string pay(int cents) override {
        if (cents > 50000) throw PaymentError("limit");
        return "card:" + std::to_string(cents);
    }
};
struct WalletPay : IPayMethod {
    std::string pay(int cents) override { return "wallet:" + std::to_string(cents); }
};
class Checkout {
    /* ② */
public:
    explicit Checkout(std::unique_ptr<IPayMethod> m) : method_(std::move(m)) {}
    std::string submit(int cents) {
        try { return method_->pay(cents); }
        /* ③ */ { return std::string("failed:") + e.what(); }
    }
};
```

questions.answer:
三空为：① virtual ~IDataSource() = default; ② std::unique_ptr<IDataSource> inner_; ③ return "E(" + inner_->write(s) + ")";。完整结构中 FileSource 是 ConcreteComponent，Wrapper 是 Decorator，Zip 与 Encrypt 是 ConcreteDecorator：
```cpp
struct IDataSource { virtual ~IDataSource() = default; virtual std::string write(std::string)=0; };
struct FileSource final : IDataSource { std::string write(std::string s) override { return "F("+s+")"; } };
class Wrapper : public IDataSource {
protected: std::unique_ptr<IDataSource> inner_;
public: explicit Wrapper(std::unique_ptr<IDataSource> p):inner_(std::move(p)){}
};
struct Zip final : Wrapper { using Wrapper::Wrapper; std::string write(std::string s) override { return "Z("+inner_->write(s)+")"; } };
struct Encrypt final : Wrapper { using Wrapper::Wrapper; std::string write(std::string s) override { return "E("+inner_->write(s)+")"; } };
```
构造 `Encrypt(Zip(FileSource))` 后调用 write("x")：先进入 Encrypt，再进入 Zip，再到 FileSource；返回时依次包装成 `F(x)`、`Z(F(x))`、`E(Z(F(x)))`。最外层 unique_ptr 销毁时，Encrypt→Wrapper 持有的 Zip→其持有的 FileSource 递归释放；IDataSource 的虚析构使每一层动态类型正确销毁。

questions.case_material:
文件写入接口需要可选叠加压缩与加密，任一层仍保持相同 write 接口。每个包装对象独占下一层，测试实现用 F、Z、E 标记调用结果。假设每层传入的对象非空。本题的 write 返回调用路径标记，不实现真实压缩或加密。补全三个空，并分析 `Encrypt(Zip(FileSource)).write("x")`。
```cpp
#include <memory>
#include <string>
#include <utility>
struct IDataSource {
    /* ① */
    virtual std::string write(std::string s) = 0;
};
struct FileSource : IDataSource {
    std::string write(std::string s) override { return "F(" + s + ")"; }
};
class Wrapper : public IDataSource {
protected:
    /* ② */
public:
    explicit Wrapper(std::unique_ptr<IDataSource> p) : inner_(std::move(p)) {}
};
struct Zip : Wrapper {
    using Wrapper::Wrapper;
    std::string write(std::string s) override { return "Z(" + inner_->write(s) + ")"; }
};
struct Encrypt : Wrapper {
    using Wrapper::Wrapper;
    std::string write(std::string s) override { /* ③ */ }
};
```

questions.answer:
三空为：① virtual ~ICommand() = default; ② cmd->execute(); ③ history_.push_back(std::move(cmd));。完整 invoker 为：
```cpp
struct ICommand { virtual ~ICommand()=default; virtual void execute()=0; virtual void undo()=0; };
class Editor {
    std::vector<std::unique_ptr<ICommand>> history_;
public:
    void run(std::unique_ptr<ICommand> cmd) { cmd->execute(); history_.push_back(std::move(cmd)); }
    void undoLast() { if(history_.empty()) return; history_.back()->undo(); history_.pop_back(); }
};
```
Document 是 Receiver；InsertCommand 是 ConcreteCommand，保存 Document&、位置和文本；Editor 是 Invoker。初始 `ab`，Insert(2,`X`) 成功后文本为 `abX`、历史数为 1；undoLast 调用同一命令 undo，文本恢复 `ab`、历史数为 0。若 Insert(9,`Y`) 的 execute 在范围检查时抛 out_of_range，语句③尚未执行，history 仍为 0，Document 仍为 `ab`。异常继续传播给 Editor 的调用者，由应用边界决定显示错误。

questions.case_material:
Document 初始文本为 `ab`。InsertCommand 保存 Document 引用、位置与文本；位置超过当前长度时 execute 抛出 std::out_of_range，且在插入前完成检查。Editor 只记录成功命令。Document 的寿命覆盖所有命令；本题只分析位置越界异常，假设分配及历史栈扩容成功。补全三个空，先执行 Insert(2,`X`) 并撤销，再执行 Insert(9,`Y`)。
```cpp
#include <memory>
#include <string>
#include <utility>
#include <vector>
#include <stdexcept>
struct Document { std::string text = "ab"; };
struct ICommand {
    /* ① */
    virtual void execute() = 0;
    virtual void undo() = 0;
};
struct InsertCommand : ICommand {
    Document& document;
    std::size_t position;
    std::string inserted;
    InsertCommand(Document& d, std::size_t p, std::string value)
        : document(d), position(p), inserted(std::move(value)) {}
    void execute() override {
        if (position > document.text.size()) throw std::out_of_range("position");
        document.text.insert(position, inserted);
    }
    void undo() override { document.text.erase(position, inserted.size()); }
};
class Editor {
    std::vector<std::unique_ptr<ICommand>> history_;
public:
    void run(std::unique_ptr<ICommand> cmd) {
        /* ② */
        /* ③ */
    }
    void undoLast() {
        if (history_.empty()) return;
        history_.back()->undo();
        history_.pop_back();
    }
};
```
